-- Lockin's D1 schema (SPEC.md §4.6). Nothing reads it until M2; it's here so the shape is settled
-- and migrations start at 0001.
--
-- Conventions:
--   * Ids are 10-character base62 strings generated by the server, except events.id (below).
--   * Times are INTEGER Unix seconds, except the participants timer columns, which are REAL so they
--     carry exactly the Double the Live Activity shows (member b/e/q in SPEC.md §4.3) and the room
--     can rebuild a content-state without rounding anyone's countdown.
--   * Booleans are INTEGER 0/1.
--   * D1 enforces foreign keys. Deleting a users row (account deletion, M2) cascades to everything
--     that's only theirs; shared history (squads they own, sessions they hosted) stays, without them.

CREATE TABLE users (
  id           TEXT    PRIMARY KEY,
  -- Sign in with Apple's stable user id. NULL once the account is deleted, so the same Apple ID
  -- can sign up again while the row waits to be purged.
  apple_sub    TEXT    UNIQUE,
  -- Chosen in the handle picker after sign-in (M2), so NULL until then. Unique ignoring case.
  handle       TEXT    UNIQUE COLLATE NOCASE,
  -- The Live Activity's `n`. SQLite's length() counts code points, as the server's validator does
  -- (src/liveActivity.ts). NULL until picked (M2).
  display_name TEXT    CHECK (length(display_name) BETWEEN 1 AND 12),
  avatar_code  TEXT    NOT NULL DEFAULT 'b0.c0.e0.h0',
  coins        INTEGER NOT NULL DEFAULT 0 CHECK (coins >= 0),
  plus_until   INTEGER,
  created_at   INTEGER NOT NULL,
  deleted_at   INTEGER
);

-- Stored in both directions, so "my friends" is one primary-key range.
CREATE TABLE friendships (
  user_id    TEXT    NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  friend_id  TEXT    NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  created_at INTEGER NOT NULL,
  PRIMARY KEY (user_id, friend_id),
  CHECK (user_id <> friend_id)
);
CREATE INDEX friendships_friend ON friendships (friend_id);

CREATE TABLE blocks (
  user_id    TEXT    NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  blocked_id TEXT    NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  created_at INTEGER NOT NULL,
  PRIMARY KEY (user_id, blocked_id),
  CHECK (user_id <> blocked_id)
);
-- "Has anyone involved blocked me?" when a code is redeemed or a squad joined.
CREATE INDEX blocks_blocked ON blocks (blocked_id);

CREATE TABLE reports (
  id             TEXT    PRIMARY KEY,
  -- Kept for moderation if the reporter deletes their account.
  reporter_id    TEXT    REFERENCES users (id) ON DELETE SET NULL,
  target_user_id TEXT    NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  reason         TEXT    NOT NULL,
  created_at     INTEGER NOT NULL
);
CREATE INDEX reports_target ON reports (target_user_id, created_at);
CREATE INDEX reports_reporter ON reports (reporter_id);

CREATE TABLE squads (
  id              TEXT    PRIMARY KEY,
  -- The Live Activity's `sq`, in code points like display_name.
  name            TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 20),
  -- NULL only between the owner deleting their account and M2 handing the squad to someone else.
  owner_id        TEXT    REFERENCES users (id) ON DELETE SET NULL,
  -- NULL while the pet is still an egg; it hatches on the first completed group session (M5).
  pet_species     TEXT,
  pet_xp          INTEGER NOT NULL DEFAULT 0 CHECK (pet_xp >= 0),
  -- 0 egg, 1 baby, 2 teen, 3 adult, 4+ prestige forms (SPEC.md §1.5).
  pet_stage       INTEGER NOT NULL DEFAULT 0 CHECK (pet_stage >= 0),
  streak_count    INTEGER NOT NULL DEFAULT 0 CHECK (streak_count >= 0),
  -- A calendar day, not a time: 'YYYY-MM-DD' (M5 decides whose time zone it is).
  streak_last_day TEXT    CHECK (streak_last_day GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  created_at      INTEGER NOT NULL
);
CREATE INDEX squads_owner ON squads (owner_id);

CREATE TABLE squad_members (
  squad_id  TEXT    NOT NULL REFERENCES squads (id) ON DELETE CASCADE,
  user_id   TEXT    NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  joined_at INTEGER NOT NULL,
  -- Mutes "X is locking in" notifications from this squad.
  muted     INTEGER NOT NULL DEFAULT 0 CHECK (muted IN (0, 1)),
  PRIMARY KEY (squad_id, user_id)
);
-- "My squads".
CREATE INDEX squad_members_user ON squad_members (user_id);

CREATE TABLE invite_codes (
  code       TEXT    PRIMARY KEY,
  kind       TEXT    NOT NULL CHECK (kind IN ('friend', 'squad')),
  -- The user to befriend or the squad to join, by kind. No foreign key because it points at either
  -- table, so redeeming (M2) checks the target still exists.
  target_id  TEXT    NOT NULL,
  created_by TEXT    NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  -- NULL never expires.
  expires_at INTEGER
);
CREATE INDEX invite_codes_target ON invite_codes (kind, target_id);
CREATE INDEX invite_codes_creator ON invite_codes (created_by);

CREATE TABLE devices (
  id                  TEXT    PRIMARY KEY,
  user_id             TEXT    NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  -- Hex. Unique, so a phone that signs into another account moves its token rather than doubling it.
  apns_token          TEXT    NOT NULL UNIQUE,
  -- Debug builds get sandbox tokens; TestFlight and App Store builds get production ones.
  apns_env            TEXT    NOT NULL CHECK (apns_env IN ('sandbox', 'production')),
  push_to_start_token TEXT,
  -- Whether Live Activities are allowed in Settings, and ActivityKit's frequent-updates switch.
  la_enabled          INTEGER NOT NULL DEFAULT 1 CHECK (la_enabled IN (0, 1)),
  frequent_pushes     INTEGER NOT NULL DEFAULT 0 CHECK (frequent_pushes IN (0, 1)),
  -- IANA name, e.g. 'Australia/Sydney': quiet hours, streak days and the weekly reset are local.
  tz                  TEXT    NOT NULL,
  updated_at          INTEGER NOT NULL
);
CREATE INDEX devices_user ON devices (user_id);

CREATE TABLE sessions (
  id         TEXT    PRIMARY KEY,
  -- NULL for a solo session, or once the squad is deleted.
  squad_id   TEXT    REFERENCES squads (id) ON DELETE SET NULL,
  -- NULL only once the host has deleted their account; the others' history stays.
  host_id    TEXT    REFERENCES users (id) ON DELETE SET NULL,
  -- The room ends when the last member finishes or leaves (SPEC.md §1.4).
  status     TEXT    NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'ended')),
  created_at INTEGER NOT NULL,
  ended_at   INTEGER,
  CHECK ((status = 'ended') = (ended_at IS NOT NULL))
);
CREATE INDEX sessions_squad ON sessions (squad_id, created_at);
CREATE INDEX sessions_host ON sessions (host_id);
CREATE INDEX sessions_open ON sessions (created_at) WHERE status = 'open';

CREATE TABLE participants (
  session_id  TEXT    NOT NULL REFERENCES sessions (id) ON DELETE CASCADE,
  user_id     TEXT    NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  -- The Live Activity member state: 0 focusing, 1 break, 2 paused, 3 done, 4 left, 5 slipped.
  state       INTEGER NOT NULL DEFAULT 0 CHECK (state BETWEEN 0 AND 5),
  -- Sessions are capped at 4 hours (SPEC.md §1.4).
  planned_min INTEGER NOT NULL CHECK (planned_min BETWEEN 1 AND 240),
  -- REAL Unix seconds: the member's b, e and q exactly as the Live Activity carries them.
  started_at  REAL    NOT NULL,
  ends_at     REAL    NOT NULL,
  paused_at   REAL,
  ended_at    REAL,
  focused_sec INTEGER NOT NULL DEFAULT 0 CHECK (focused_sec >= 0),
  -- The activity's push token (hex). Arrives after joining and can change, so it's nullable.
  la_token    TEXT,
  slips       INTEGER NOT NULL DEFAULT 0 CHECK (slips >= 0),
  PRIMARY KEY (session_id, user_id),
  CHECK (ends_at >= started_at),
  CHECK ((state = 2) = (paused_at IS NOT NULL))
);
-- Stats, history and the weekly leaderboard per user.
CREATE INDEX participants_user ON participants (user_id, started_at);

-- For stats and debugging (SPEC.md §4.6), including push counts per room (§4.4). Never referred to
-- from outside, so the id is SQLite's rowid rather than a base62 string.
CREATE TABLE events (
  id         INTEGER PRIMARY KEY,
  session_id TEXT    REFERENCES sessions (id) ON DELETE CASCADE,
  user_id    TEXT    REFERENCES users (id) ON DELETE CASCADE,
  type       TEXT    NOT NULL,
  at         INTEGER NOT NULL,
  meta_json  TEXT    CHECK (meta_json IS NULL OR json_valid(meta_json))
);
CREATE INDEX events_session ON events (session_id, at);
CREATE INDEX events_user ON events (user_id, at);
CREATE INDEX events_type ON events (type, at);

CREATE TABLE cosmetics (
  user_id     TEXT    NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  -- A catalogue code, e.g. 'hat.crown'.
  item_id     TEXT    NOT NULL,
  acquired_at INTEGER NOT NULL,
  PRIMARY KEY (user_id, item_id)
);
